package containers

import (
	"context"
	"errors"
	"fmt"
	"net/netip"
	"sort"
	"strings"
	"time"
)

type RecipeVerifier interface{Verify(context.Context,ApplicationRecipe)error}
type IDAllocator interface{For(context.Context,ID,string,string)(ID,error)}
type ApplicationService struct{containers *Service;repository Repository;verifier RecipeVerifier;allocator IDAllocator;clock func()time.Time}
func NewApplicationService(containers *Service,repository Repository,verifier RecipeVerifier,allocator IDAllocator)(*ApplicationService,error){if containers==nil||nilValue(repository)||nilValue(verifier)||nilValue(allocator){return nil,ErrInvalid};return &ApplicationService{containers:containers,repository:repository,verifier:verifier,allocator:allocator,clock:time.Now},nil}
func(a *ApplicationService)RegisterRecipe(ctx context.Context,recipe ApplicationRecipe)error{if !recipe.ID.Valid()||recipe.Version==""||recipe.SigningKeyID==""||recipe.Signature==""||len(recipe.Digest)!=64||len(recipe.SignatureDigest)!=64||len(recipe.Workloads)==0{return ErrInvalid};if err:=a.verifier.Verify(ctx,recipe);err!=nil{return err};names:=map[string]bool{};for _,workload:=range recipe.Workloads{if names[workload.Name]{return ErrConflict};names[workload.Name]=true;if err:=workload.Spec.Validate(TierTenantRootless);err!=nil{return err}};return a.repository.PutRecipe(ctx,recipe)}

type DeployApplicationCommand struct{Meta CommandMeta;ApplicationID,SiteID,RecipeID ID;RecipeVersion string;SecretBindings map[string]string}
func(a *ApplicationService)Deploy(ctx context.Context,command DeployApplicationCommand)(ContainerApplication,[]Result,error){now:=a.clock().UTC();if err:=command.Meta.Validate("application.deploy",command.ApplicationID,now);err!=nil{return ContainerApplication{},nil,err};recipe,err:=a.repository.Recipe(ctx,command.RecipeID,command.RecipeVersion);if err!=nil{return ContainerApplication{},nil,err};if err=a.verifier.Verify(ctx,recipe);err!=nil{return ContainerApplication{},nil,err};application:=ContainerApplication{ID:command.ApplicationID,TenantID:command.Meta.Grant.TenantID,SiteID:command.SiteID,RecipeID:recipe.ID,RecipeVersion:recipe.Version,State:"deploying",ActiveGeneration:command.Meta.ExpectedGeneration+1,CandidateGeneration:command.Meta.ExpectedGeneration+1,CreatedAt:now,UpdatedAt:now};if command.Meta.ExpectedGeneration>0{previous,e:=a.repository.Application(ctx,application.TenantID,application.ID);if e!=nil{return application,nil,e};application.CreatedAt=previous.CreatedAt;application.FirstWriteAt=previous.FirstWriteAt;application.DataGeneration=previous.DataGeneration};proposal:=application;for _,v:=range recipe.Volumes{id,e:=a.allocator.For(ctx,application.ID,"volume",v.Name);if e!=nil{return application,nil,e};proposal.VolumeIDs=append(proposal.VolumeIDs,id)};for _,v:=range recipe.Networks{id,e:=a.allocator.For(ctx,application.ID,"network",v.Name);if e!=nil{return application,nil,e};proposal.NetworkIDs=append(proposal.NetworkIDs,id)};ordered,err:=sortRecipeWorkloads(recipe.Workloads);if err!=nil{return application,nil,err};for _,v:=range ordered{id,e:=a.allocator.For(ctx,application.ID,"workload",v.Name);if e!=nil{return application,nil,e};proposal.WorkloadIDs=append(proposal.WorkloadIDs,id)};operation:=Operation{EffectID:EffectID("app-"+digestValue(command)),TenantID:application.TenantID,ResourceID:application.ID,CommandDigest:digestValue(command),Status:"accepted",CreatedAt:now};admitted,err:=a.repository.Admit(ctx,operation,proposal,command.Meta.ExpectedGeneration);if err!=nil{return application,nil,err};if !admitted{current,e:=a.repository.Application(ctx,application.TenantID,application.ID);if e!=nil{return application,nil,e};if current.State!="active"{return current,nil,ErrAmbiguous};return current,nil,nil};completed:=false;defer func(){if !completed{proposal.State="recovery_required";cleanup,cancel:=context.WithTimeout(context.WithoutCancel(ctx),10*time.Second);defer cancel();_=a.repository.Complete(cleanup,operation.EffectID,"ambiguous",proposal,map[string]string{"state":"recovery_required"})}}();results:=make([]Result,0);for _,volumeSpec:=range recipe.Volumes{id,allocErr:=a.allocator.For(ctx,application.ID,"volume",volumeSpec.Name);if allocErr!=nil{return application,results,allocErr};meta:=deriveMeta(command.Meta,"volume.ensure",id,volumeSpec.Name);if command.Meta.ExpectedGeneration>0{previous,e:=a.repository.Volume(ctx,application.TenantID,id);if e!=nil{return application,results,e};if previous.Class!=volumeSpec.Class||previous.QuotaBytes!=volumeSpec.QuotaBytes||previous.InodeLimit!=volumeSpec.InodeLimit{return application,results,ErrConflict};application.VolumeIDs=append(application.VolumeIDs,id);continue};_,result,ensureErr:=a.containers.EnsureVolume(ctx,EnsureVolumeCommand{Meta:meta,VolumeID:id,Name:volumeSpec.Name,Class:volumeSpec.Class,QuotaBytes:volumeSpec.QuotaBytes,InodeLimit:volumeSpec.InodeLimit});if ensureErr!=nil{return application,results,ensureErr};application.VolumeIDs=append(application.VolumeIDs,id);results=append(results,result)};for _,networkSpec:=range recipe.Networks{id,allocErr:=a.allocator.For(ctx,application.ID,"network",networkSpec.Name);if allocErr!=nil{return application,results,allocErr};prefix:=netip.MustParsePrefix("10.0.0.0/24");meta:=deriveMeta(command.Meta,"network.ensure",id,networkSpec.Name);if command.Meta.ExpectedGeneration>0{if _,e:=a.repository.Network(ctx,application.TenantID,id);e!=nil{return application,results,e};application.NetworkIDs=append(application.NetworkIDs,id);continue};_,result,ensureErr:=a.containers.EnsureNetwork(ctx,EnsureNetworkCommand{Meta:meta,NetworkID:id,Name:networkSpec.Name,IPv4:prefix,Internal:networkSpec.Internal,DNSPolicy:"internal"});if ensureErr!=nil{return application,results,ensureErr};application.NetworkIDs=append(application.NetworkIDs,id);results=append(results,result)};for _,workloadSpec:=range ordered{id,allocErr:=a.allocator.For(ctx,application.ID,"workload",workloadSpec.Name);if allocErr!=nil{return application,results,allocErr};spec:=workloadSpec.Spec;spec.Environment=append([]EnvironmentValue(nil),spec.Environment...);spec.Volumes=append([]VolumeMount(nil),spec.Volumes...);spec.Networks=append([]NetworkAttachment(nil),spec.Networks...);for index,entry:=range spec.Environment{if strings.HasPrefix(entry.SecretRef,"secret_n8n_"){binding:=command.SecretBindings[entry.SecretRef];if _,bindingErr:=NewID(binding);bindingErr!=nil{return application,results,fmt.Errorf("%w: missing recipe secret %s",ErrInvalid,entry.SecretRef)};spec.Environment[index].SecretRef=binding}};for index,mount:=range spec.Volumes{for recipeIndex,recipeVolume:=range recipe.Volumes{if mount.VolumeID.String()==recipeVolume.Name||mount.VolumeID.String()=="vol_"+recipeVolume.Name{spec.Volumes[index].VolumeID=application.VolumeIDs[recipeIndex]}}};for index,attachment:=range spec.Networks{for recipeIndex,recipeNetwork:=range recipe.Networks{if attachment.NetworkID.String()==recipeNetwork.Name||attachment.NetworkID.String()=="net_"+recipeNetwork.Name{spec.Networks[index].NetworkID=application.NetworkIDs[recipeIndex]}}};meta:=deriveMeta(command.Meta,"workload.apply",id,workloadSpec.Name);if command.Meta.ExpectedGeneration>0{previous,e:=a.repository.Workload(ctx,application.TenantID,id);if e!=nil{return application,results,e};meta.ExpectedGeneration=previous.Generation;meta.Fence=FenceToken(previous.Generation+1)};_,result,applyErr:=a.containers.ApplyWorkload(ctx,ApplyWorkloadCommand{Meta:meta,WorkloadID:id,SiteID:application.SiteID,Name:workloadSpec.Name,Tier:TierTenantRootless,Spec:spec});if applyErr!=nil{return application,results,applyErr};application.WorkloadIDs=append(application.WorkloadIDs,id);results=append(results,result)};application.State="active";application.CandidateGeneration=0;if err=a.repository.Complete(ctx,operation.EffectID,"applied",application,map[string]any{"results":results});err!=nil{return application,results,err};completed=true;return application,results,nil}

type UpdateApplicationCommand struct{Meta CommandMeta;ApplicationID ID;RecipeID ID;RecipeVersion string;BackwardCompatibleData bool;SecretBindings map[string]string}
func(a *ApplicationService)Update(ctx context.Context,command UpdateApplicationCommand)(ContainerApplication,[]Result,error){
 application,err:=a.repository.Application(ctx,command.Meta.Grant.TenantID,command.ApplicationID);if err!=nil{return ContainerApplication{},nil,err}
 if application.ActiveGeneration!=command.Meta.ExpectedGeneration||application.State!="active"{return application,nil,ErrStale}
 if err=command.Meta.Validate("application.deploy",application.ID,a.clock().UTC());err!=nil{return application,nil,err}
 recipe,err:=a.repository.Recipe(ctx,command.RecipeID,command.RecipeVersion);if err!=nil{return application,nil,err}
 if err=a.verifier.Verify(ctx,recipe);err!=nil{return application,nil,err}
 ordered,err:=sortRecipeWorkloads(recipe.Workloads);if err!=nil{return application,nil,err}
 if len(ordered)!=len(application.WorkloadIDs)||len(recipe.Volumes)!=len(application.VolumeIDs)||len(recipe.Networks)!=len(application.NetworkIDs){return application,nil,fmt.Errorf("%w: topology migrations need a recovery plan",ErrConflict)}
 for _,workload:=range ordered{id,e:=a.allocator.For(ctx,application.ID,"workload",workload.Name);if e!=nil{return application,nil,e};found:=false;for _,existing:=range application.WorkloadIDs{if existing==id{found=true}};if !found{return application,nil,ErrConflict};for _,entry:=range workload.Spec.Environment{if strings.HasPrefix(entry.SecretRef,"secret_n8n_"){if _,e=NewID(command.SecretBindings[entry.SecretRef]);e!=nil{return application,nil,fmt.Errorf("%w: missing secret binding",ErrInvalid)}}}}
 for _,volume:=range recipe.Volumes{id,e:=a.allocator.For(ctx,application.ID,"volume",volume.Name);if e!=nil{return application,nil,e};existing,e:=a.repository.Volume(ctx,application.TenantID,id);if e!=nil{return application,nil,e};if existing.Class!=volume.Class||existing.QuotaBytes!=volume.QuotaBytes||existing.InodeLimit!=volume.InodeLimit{return application,nil,ErrConflict}}
 for _,network:=range recipe.Networks{id,e:=a.allocator.For(ctx,application.ID,"network",network.Name);if e!=nil{return application,nil,e};if _,e=a.repository.Network(ctx,application.TenantID,id);e!=nil{return application,nil,e};if !network.Internal{return application,nil,ErrPolicy}}
 // Quiesce all processes before the broker snapshots every persistent volume.
 for index:=len(application.WorkloadIDs)-1;index>=0;index--{id:=application.WorkloadIDs[index];workload,e:=a.repository.Workload(ctx,application.TenantID,id);if e!=nil{return application,nil,e};meta:=deriveMeta(command.Meta,"workload.lifecycle",id,"quiesce-"+id.String());meta.ExpectedGeneration=workload.Generation;meta.Fence=FenceToken(workload.Generation+1);quiesced,_,e:=a.containers.SetLifecycle(ctx,LifecycleCommand{Meta:meta,WorkloadID:id,Lifecycle:LifecycleStopped});if e!=nil{return application,nil,e};if quiesced.ObservedLifecycle!=LifecycleStopped{return application,nil,fmt.Errorf("%w: snapshot requires stopped writers",ErrAmbiguous)}}
 // An update-specific identity prevents replaying an older recovery snapshot.
 snapshotID,err:=a.allocator.For(ctx,application.ID,"snapshot",command.Meta.CommandID);if err!=nil{return application,nil,err}
 snapshotVolumes:=append([]ID(nil),application.VolumeIDs...);sort.Slice(snapshotVolumes,func(i,j int)bool{return snapshotVolumes[i]<snapshotVolumes[j]})
 snapshotEffect:=EffectID("update-snapshot-"+digestValue(command));snapshotStarted:=a.clock().UTC()
 snapshotReceipt,err:=a.containers.broker.SnapshotVolumes(ctx,VolumeSnapshotRequest{EffectID:snapshotEffect,SnapshotID:snapshotID,TenantID:application.TenantID,ApplicationID:application.ID,VolumeIDs:snapshotVolumes,Fence:command.Meta.Fence})
 if err!=nil||snapshotReceipt.Outcome!="confirmed"||snapshotReceipt.EffectID!=snapshotEffect||snapshotReceipt.SnapshotID!=snapshotID||snapshotReceipt.ApplicationID!=application.ID||snapshotReceipt.Fence!=command.Meta.Fence||len(snapshotReceipt.ManifestDigest)!=64||snapshotReceipt.Bytes==0||snapshotReceipt.ObservedAt.IsZero()||snapshotReceipt.CompletedAt.Before(snapshotStarted)||!sameProtocolIDs(snapshotVolumes,snapshotReceipt.VolumeIDs){return application,nil,fmt.Errorf("%w: fresh verified recovery snapshot unavailable: %v",ErrConflict,err)}
 snapshot:=snapshotID.String()
 // Persist the unknown-write frontier before any candidate process can run.
 application.State="updating";written:=a.clock().UTC();application.FirstWriteAt=&written;application.CandidateGeneration=application.ActiveGeneration+1
 operation:=Operation{EffectID:EffectID("frontier-"+digestValue(command)),TenantID:application.TenantID,ResourceID:application.ID,CommandDigest:digestValue(command),Status:"accepted",CreatedAt:written}
 application.ActiveGeneration++
 if _,err=a.repository.Admit(ctx,operation,application,command.Meta.ExpectedGeneration);err!=nil{return application,nil,err}
 if err=a.repository.Complete(ctx,operation.EffectID,"applied",application,map[string]any{"snapshot":snapshot,"write_frontier":"unknown"});err!=nil{return application,nil,err}
 meta:=command.Meta;meta.ExpectedGeneration=application.ActiveGeneration
 // Never auto-restore a snapshot after candidate writes may have begun.
 return a.Deploy(ctx,DeployApplicationCommand{Meta:meta,ApplicationID:application.ID,SiteID:application.SiteID,RecipeID:command.RecipeID,RecipeVersion:command.RecipeVersion,SecretBindings:command.SecretBindings})
}

func(a *ApplicationService)Rollback(ctx context.Context,tenant,applicationID ID,snapshot string,previous ContainerApplication)(ContainerApplication,error){current,err:=a.repository.Application(ctx,tenant,applicationID);if err!=nil{return ContainerApplication{},err};if current.FirstWriteAt!=nil||current.DataGeneration!=previous.DataGeneration{return current,fmt.Errorf("%w: application crossed write frontier",ErrConflict)};if err=a.containers.backups.RestoreVolumes(ctx,snapshot,previous.VolumeIDs);err!=nil{return current,err};previous.UpdatedAt=a.clock().UTC();return previous,nil}

func deriveMeta(parent CommandMeta,operation string,resource ID,variant string)CommandMeta{parent.CommandID=parent.CommandID+"."+variant;parent.Grant.Operation=operation;parent.Grant.ResourceID=resource;parent.Grant.Digest=digestValue(struct{Parent,Operation,Resource string}{parent.CommandID,operation,resource.String()});parent.ExpectedGeneration=0;parent.Fence++;return parent}
func sortRecipeWorkloads(values []RecipeWorkload)([]RecipeWorkload,error){remaining:=make(map[string]RecipeWorkload,len(values));for _,value:=range values{if value.Name==""{return nil,ErrInvalid};if _,exists:=remaining[value.Name];exists{return nil,ErrConflict};remaining[value.Name]=value};for _,value:=range values{for _,dependency:=range value.DependsOn{if _,exists:=remaining[dependency];!exists{return nil,ErrInvalid}}};result:=make([]RecipeWorkload,0,len(values));for len(remaining)>0{names:=make([]string,0,len(remaining));for name:=range remaining{names=append(names,name)};sort.Strings(names);progress:=false;for _,name:=range names{value:=remaining[name];ready:=true;for _,dependency:=range value.DependsOn{if _,pending:=remaining[dependency];pending{ready=false;break}};if ready{result=append(result,value);delete(remaining,name);progress=true}};if !progress{return nil,errors.New("container recipe dependency cycle")}};return result,nil}
